    getChartOptions() {
        return this.chartOptions;
    }
    createChart(container: HTMLElement | null) {
        if (container) {
            const chart = createChart(container, this.chartOptions);
            return chart; // 명시적으로 chart 객체 반환
        }
        throw new Error('Container element is required'); // null인 경우 에러 발생
    }
    createSeries(container: any, type: string, option: 'candleOptions' | 'pinkOptions' | 'aoSeriesOptions') {

        let optionVal = this[option]
        // let {decimalPlaces,decimalScale } = priceFormat
        // if(option !=="RSI"){ // except rsi , all indicator use candle priceScale*0.01
        //     optionVal.priceFormat.precision = (decimalPlaces+2);
        //     if(optionVal.priceFormat?.minMove !== undefined){
        //         optionVal.priceFormat.minMove = (Number(decimalScale)*0.01).toFixed(decimalPlaces+2)
        //     }
        // }

        if (type === 'candle') {
            return container.addCandlestickSeries(optionVal)
        } else if (type === 'line') {
            return container.addLineSeries(optionVal)
        } else if (type === 'baseLine') {
            return container.addBaselineSeries(optionVal)
        } else if (type === 'histogram') {
            return container.addHistogramSeries(optionVal)
        } else {
            return;
        }
    }
    getRequsetUrl(id: string, isHeikin: boolean) {
        if (id === 'candle' || id === 'PINK' || id === 'AO') {
            return isHeikin ? '/candle/heikin-candle' : '/candle/candle';
        } else if (id === 'BB') {
            return isHeikin ? '/candle/heikin-bb' : '/candle/candle-bb';
        }else if(id === 'MA3'){
            return isHeikin ? '/candle/heikin-ma' : '/candle/candle-ma';
        } else if(id === 'TREND'){
            return '/analysis/multiple-trend';
        } else if(id === 'SR'){
            return '/candle/sr';
        } else if(id === 'RSI'){
            return '/candle/rsi';
        } else if(id === 'MACD'){
            return isHeikin ? '/candle/heikin-macd' : '/candle/candle-macd';
        } else {
            return '';
        }
    }
    getRSIPriceLine(name: keyof SignalChartOptions) {
        return this[`${name}`]
    }
    setPriceFormat(series: any, option: any, priceFormat: any){
        let {decimalPlaces, decimalScale} = priceFormat
        // console.log('series',series,'option',option);
        if(option !== 'RSILineOptions' || option !== 'MACDLineOrangeOptions' || option !== 'MACDLineBlueOptions' || option !== 'MACDHistogramOptions'){
            series.applyOptions({
                priceFormat: {
                    precision: decimalPlaces ? decimalPlaces+2 : 5,
                    minMove: decimalScale ? (Number(decimalScale)*0.01).toFixed(decimalPlaces+2) : 0.00001,
                },
            });
        }
    }    
