import { theme } from "../../styles/theme";
import { ButtonMedium } from '../../styles/common/Button';
import styled from 'styled-components';
import { useCallback, useContext, useEffect, useMemo, useState } from "react";
import { PublicKey, Connection } from '@solana/web3.js';
import * as solanaWeb3 from '@solana/web3.js';
import * as splToken from '@solana/spl-token';
import MessageModal from "../modal/MessageModal";
import { walletText } from '../../utils/wallet/walletText';
import { useWalletContext } from '../../contexts/WalletContextProvider';
import { detectMobileDevice } from '../../utils/sizeUtils';
import { OKXUniversalProvider } from "@okxconnect/universal-provider";
import { OKXSolanaProvider } from "@okxconnect/solana-provider";

interface TokenBalance {
    mint: string;
    symbol: string;
    amount: number;
}

const WalletList = styled.div`
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:1rem;
    padding: 1rem 1.5rem;
    background: rgba(255, 255, 255, 0.05);
`;

const WalletItem = styled.div`
    display:flex;
    align-items:center;
    gap:1rem;
    @media screen and (max-width : 576px ){
        button { display:none; }
    }    
`;

export default function OKXWallet() {
    const [actionType, setActionType] = useState<string>('');
    const [isOpen, setIsOpen] = useState<boolean>(false);
    const [publicKey, setPublicKey] = useState<string | null>(null);
    const [connected, setConnected] = useState<boolean>(false);
    const [tokenBalances, setTokenBalances] = useState<TokenBalance[]>([]);
    const [isMobile, setIsMobile] = useState<boolean>(false);
    const [isOKXInstalled, setIsOKXInstalled] = useState<boolean>(false);
    const { setIsWalletConnected, setWalletName, isWalletConnected } = useWalletContext();
    const walletName = 'OKX';
    useEffect(() => {
        const checkMobile = () => {
            setIsMobile(detectMobileDevice());
        };

        checkMobile();
        window.addEventListener('resize', checkMobile);

        return () => {
            window.removeEventListener('resize', checkMobile);
        };
    }, []);

    // OKX 지갑 제공자 확인
    const getOKXProvider = () => {
        console.log('okxwallet', 'okxwallet' in window);
        if ('okxwallet' in window) {
            setIsOKXInstalled(true);
            return (window as any).okxwallet;
        } else {
            setIsOKXInstalled(false);
            return null;
        }
    };

    // 토큰 심볼 매핑 (실제 구현에서는 더 많은 토큰 추가 필요)
    const getTokenSymbol = (mintAddress: string): string => {
        const tokenMap: Record<string, string> = {
            'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v': 'USDC',
            'Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB': 'USDT',
            'So11111111111111111111111111111111111111112': 'SOL',
            // 더 많은 토큰 추가
        };

        return tokenMap[mintAddress] || 'Unknown';
    };

    // 토큰 잔액 조회
    const fetchTokenBalances = async (publicKey: string) => {
        try {
            const connection = new solanaWeb3.Connection(
                // solanaWeb3.clusterApiUrl('mainnet-beta')
                'https://winter-evocative-silence.solana-mainnet.quiknode.pro/04a5e639b0bd9ceeec758a6140dc1aa1b08f62bd', // 또는 다른 신뢰할 수 있는 RPC 제공자
            );

            // 사용자의 모든 토큰 계정 조회
            const tokenAccounts = await connection.getParsedTokenAccountsByOwner(
                new solanaWeb3.PublicKey(publicKey),
                {
                    programId: new solanaWeb3.PublicKey(splToken.TOKEN_PROGRAM_ID),
                }
            );

            // 토큰 정보 추출
            const balances = tokenAccounts.value.map(account => {
                const accountData = account.account.data.parsed.info;
                const mintAddress = accountData.mint;
                const amount = accountData.tokenAmount.uiAmount;

                return {
                    mint: mintAddress,
                    symbol: getTokenSymbol(mintAddress), // 토큰 심볼 가져오는 함수 (별도 구현 필요)
                    amount: amount
                };
            }).filter(token => token.amount > 0); // 잔액이 있는 토큰만 표시
            console.log('balances', balances);

            setTokenBalances(balances);
        } catch (error) {
            console.error('토큰 잔액 조회 실패:', error);
        }
    };

    // 모바일에서 OKX 앱 열기
    const openOKXMobile = useCallback(async () => {
        // 현재 URL을 인코딩하여 콜백 URL로 사용
        // const dappUrl = encodeURIComponent(window.location.href);

        // // OKX 앱 공식 딥링크 형식 사용
        // const deepLink = `okexchain://wallet/dapp/details?dappUrl=${dappUrl}`;

        // // 앱스토어 링크 (앱이 설치되지 않은 경우)
        // const appStoreLink = 'https://www.okx.com/web3/wallet/download';

        // // 딥링크로 앱 열기 시도
        // window.location.href = deepLink;

        // // 타임아웃 후 앱이 열리지 않으면 앱스토어로 리디렉션
        // const timer = setTimeout(() => {
        //     window.location.href = appStoreLink;
        // }, 2000);

        // // 페이지를 떠날 때 타이머 정리
        // window.addEventListener('blur', () => {
        //     clearTimeout(timer);
        // });

        // return () => {
        //     clearTimeout(timer);
        // };
        const okxUniversalProvider = await OKXUniversalProvider.init({
            dappMetaData: {
                name: "SIGX",
                icon: "https://picsum.photos/64/64"
            },
        })
        try{
            const resp = await okxUniversalProvider.connect({
                namespaces: {
                    solana: {
                        chains: ["solana:5eykt4UsFv8P8NJdTREpY1vzqKqZKvdp"], // Solana 메인넷
                    }
                },
                sessionConfig: {
                    redirect: window.location.href // 연결 후 리다이렉트 URL
                }
            })
            alert(`지갑연결 성공 : ${resp}`)
            if (resp && resp.namespaces.solana) {
                // Solana 제공자 설정
                const solProvider = new OKXSolanaProvider(okxUniversalProvider);
                // 계정 정보 가져오기
                const account = solProvider.getAccount();
                if (account && account.address) {
                    console.log('연결된 계정:', account.address);
                    
                    // 상태 업데이트
                    setPublicKey(account.address);
                    setConnected(true);
                    setIsWalletConnected(true);
                    
                    // 로컬 스토리지에 저장
                    localStorage.setItem('publicKey', account.address);
                    localStorage.setItem('walletName', 'OKX');
                    setWalletName('OKX');
                    
                    // 성공 메시지 표시
                    setActionType('connect');
                    setIsOpen(true);
                    alert(`연결 성공 ${account.address}`)
                }
            }
        }catch(error:any){
            alert(`지갑연결 오류 : ${error.message}`)
        }
    }, []);

    // OKX 지갑 연결
    const connectOKX = useCallback(async () => {
        
        if(isWalletConnected){
            setActionType('alreadyConnected');
            setIsOpen(true);
            return;
        }
        // 모바일 환경에서는 딥링크 사용
        if (isMobile) {
            openOKXMobile(); // 모바일에서는 딥링크 함수 호출
            return;
        }

        try {
            const provider = getOKXProvider();
            console.log('연결 시도 - provider:', provider);

            if (!provider) {
                setActionType('uninstalled');
                setIsOpen(true)
                return;
            }

            // OKX 지갑 API 확인
            if (!provider.solana) {
                console.error('OKX 지갑의 Solana API를 찾을 수 없습니다.');
                return;
            }

            console.log('연결 전 상태 확인:', provider.solana);

            // Solana 체인 연결 요청
            console.log('connect 메서드 호출 시도...');
            const resp = await provider.solana.connect();
            console.log('연결 응답:', resp);

            // 연결 성공 시 공개키 저장
            if (resp && resp.publicKey) {
                const publicKeyStr = resp.publicKey.toString();
                console.log('연결 성공! publicKey:', publicKeyStr);
                setPublicKey(publicKeyStr);
                setConnected(true);
                localStorage.setItem('publicKey', publicKeyStr);
                localStorage.setItem('walletName', 'OKX');
                setWalletName('OKX');
                setIsWalletConnected(true);
                setIsOpen(true);
                setActionType('connect');
                // 토큰 잔액 조회
                await fetchTokenBalances(publicKeyStr);

                // 연결 이벤트 리스너 설정
                console.log('이벤트 리스너 설정...');

                // OKX 지갑은 'accountChanged' 대신 'accountsChanged'를 사용할 수 있습니다
                provider.solana.on('accountsChanged', async (publicKeys: any[]) => {
                    console.log('계정 변경됨:', publicKeys);
                    if (publicKeys && publicKeys.length > 0) {
                        const newPublicKey = publicKeys[0].toString();
                        setPublicKey(newPublicKey);
                        await fetchTokenBalances(newPublicKey);
                    } else {
                        setPublicKey(null);
                        setConnected(false);
                        setTokenBalances([]);
                    }
                });

                // 연결 해제 이벤트 리스너
                provider.solana.on('disconnect', () => {
                    console.log('연결 해제됨');
                    setPublicKey(null);
                    setConnected(false);
                    setTokenBalances([]);
                });
            } else {
                console.log('연결 응답에 publicKey가 없습니다:', resp);
            }
        } catch (error: any) {
            console.error('OKX 지갑 연결 오류:', error);
            if (error.code === 4001) {
                setActionType('userRejected');
                setIsOpen(true);
            }
        }
    }, [fetchTokenBalances, isMobile, openOKXMobile]);

    // 지갑 연결 해제
    const disconnectOKX = useCallback(async () => {
        try {
            const provider = getOKXProvider();

            if (provider && provider.solana && provider.solana.disconnect) {
                await provider.solana.disconnect();
            }

            setPublicKey(null);
            setConnected(false);
            setTokenBalances([]);
        } catch (error) {
            console.error('OKX 지갑 연결 해제 오류:', error);
        }
    }, []);

    // 컴포넌트 마운트 시 지갑 연결 상태 확인
    useEffect(() => {
        // 모바일에서는 URL 파라미터로 연결 상태 확인
        if (isMobile) {
            // URL에서 지갑 주소 파라미터 확인 (OKX 앱에서 리디렉션 후)
            const urlParams = new URLSearchParams(window.location.search);
            const walletAddress = urlParams.get('wallet');

            if (walletAddress) {
                setPublicKey(walletAddress);
                setConnected(true);
                fetchTokenBalances(walletAddress);
            }
            return;
        }

        // 데스크톱에서는 기존 방식으로 확인
        const checkConnection = async () => {
            const provider = getOKXProvider();

            if (provider && provider.solana) {
                try {
                    console.log('OKX 지갑 제공자 확인:', provider);
                    console.log('OKX Solana API 확인:', provider.solana);

                    // 연결 상태 디버깅
                    console.log('_publicKey:', provider.solana._publicKey);
                    console.log('isConnected 속성:', provider.solana.isConnected);

                    // isConnected는 함수가 아니라 속성입니다
                    if (provider.solana.isConnected) {
                        // 이미 연결된 경우
                        if (provider.solana._publicKey) {
                            const publicKeyStr = provider.solana._publicKey.toString();
                            console.log('기존 연결된 publicKey:', publicKeyStr);
                            setPublicKey(publicKeyStr);
                            setConnected(true);
                            await fetchTokenBalances(publicKeyStr);
                        } else {
                            console.log('연결되어 있지만 publicKey가 없습니다.');
                        }
                    } else {
                        console.log('지갑이 연결되어 있지 않습니다.');
                    }
                } catch (error) {
                    console.error('지갑 연결 상태 확인 오류:', error);
                }
            } else {
                console.log('OKX 지갑 제공자가 없거나 Solana API를 찾을 수 없습니다.');
            }
        };

        checkConnection();

        // 의존성 배열을 빈 배열로 설정하여 컴포넌트 마운트 시에만 실행되도록 함
    }, []);  // 빈 의존성 배열
    return (
        <>
            <WalletList onClick={connectOKX}>
                <WalletItem>
                    <img src={theme.icon.okx} alt="okx" />
                    <p>OKX Wallet</p>
                </WalletItem>
                <WalletItem>
                    {
                        isOKXInstalled ? (
                            <ButtonMedium bgColor={theme.color.walletBg} textColor={theme.color.mainGreen} borderColor="none">
                                <span>INSTALLED</span>
                            </ButtonMedium>
                        ) : (
                            <ButtonMedium bgColor="rgba(255, 255, 255, 0.15)" textColor={theme.color.gray} borderColor="none">
                                <span>NOT INSTALLED</span>
                            </ButtonMedium>
                        )
                    }
                    <img src={theme.icon.rightArrow} alt="right-arrow" />
                </WalletItem>
            </WalletList>
            <MessageModal action={actionType} isOpen={isOpen} setIsOpen={setIsOpen} walletName={walletName} title={walletText(walletName, actionType)?.title} content={walletText(walletName, actionType)?.content} />
        </>
    )
}