export const getCoinImg = (coin: string) => {
    return `${process.env.PUBLIC_URL}/assets/images/coin_logos/${coin.toLowerCase()}.png` ? `${process.env.PUBLIC_URL}/assets/images/coin_logos/${coin.toLowerCase()}.png` : `${process.env.PUBLIC_URL}/assets/images/coin_logos/default.png`;
}

export const getCheckImg = (checked: boolean) => {
    return checked ? `${process.env.PUBLIC_URL}/assets/images/icon/check-green.png` : `${process.env.PUBLIC_URL}/assets/images/icon/check-default-green.png`;
}

export const getDateStr = (dateStr:string) : string => {
    const year = dateStr.slice(0, 4);
    const month = dateStr.slice(4, 6);
    const day = dateStr.slice(6, 8);
    const hour = dateStr.slice(8, 10);
    return `${year}/${month}/${day} ${hour}:00`;
}

export const getHourStr = (dateStr:string) : string => {
    const month = dateStr.slice(4, 6);
    const day = dateStr.slice(6, 8);
    const hour = dateStr.slice(8, 10);
    return `${month}/${day} ${hour}:00`;
}