// TweetNaCl.js 라이브러리 사용
import nacl from 'tweetnacl';
// import { encode as encodeBase58 } from 'bs58';
// import { decode as decodeBase58 } from 'bs58';
import bs58 from 'bs58';
export const getPhantomEncryptionKey = () => {
    // 이미 생성된 키가 있는지 확인
    const storedPublicKey = localStorage.getItem('phantom_encryption_public_key');
    const storedSecretKey = localStorage.getItem('phantom_encryption_secret_key');

    if (storedPublicKey && storedSecretKey) {
        return storedPublicKey;
    }

    // 새 키 쌍 생성
    const keyPair = nacl.box.keyPair();
    const publicKeyBase58 = bs58.encode(keyPair.publicKey);
    const secretKeyBase58 = bs58.encode(keyPair.secretKey);

    // 로컬 스토리지에 저장
    localStorage.setItem('phantom_encryption_public_key', publicKeyBase58);
    localStorage.setItem('phantom_encryption_secret_key', secretKeyBase58);

    return publicKeyBase58;
};

// 공유 비밀 생성 함수 - Phantom 문서에 맞게 수정
export const createSharedSecret = (
    phantomEncryptionPublicKey: string,
    dappSecretKey: string
) => {
    try {
        // Base58 디코딩
        const phantomPublicKeyBytes = bs58.decode(phantomEncryptionPublicKey);
        const dappSecretKeyBytes = bs58.decode(dappSecretKey);

        // nacl.box.before를 사용하여 공유 비밀 생성
        // Phantom의 공개키와 Dapp의 비밀키를 사용
        const sharedSecretBytes = nacl.box.before(
            phantomPublicKeyBytes,
            dappSecretKeyBytes
        );

        return sharedSecretBytes;
    } catch (error) {
        alert(`공유 비밀 생성 오류: ${error}`);
    }
};

// 데이터 복호화 함수
export const decryptPayload = (
    encryptedDataBase58: string,
    nonceBase58: string,
    sharedSecret: Uint8Array
) => {
    try {
        // Base58 디코딩
        const encryptedData = bs58.decode(encryptedDataBase58);
        const nonce = bs58.decode(nonceBase58);

        // nacl.box.open.after를 사용하여 데이터 복호화
        const decryptedBytes = nacl.box.open.after(
            encryptedData,
            nonce,
            sharedSecret
        );

        if (!decryptedBytes) {
            alert('데이터 복호화 실패: 복호화된 데이터가 null입니다');
            return null;
        }

        // 바이트 배열을 문자열로 변환
        const decryptedString = new TextDecoder().decode(decryptedBytes);

        // JSON 파싱
        return JSON.parse(decryptedString);
    } catch (error) {
        alert(`데이터 복호화 실패: ${error}`);
    }
};